using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 [Serializable]public sealed class DetailRates{public NumberData compute,income,data,quality,efficiency;}
 [Serializable]public sealed class DetailCase{public string name,transfer,id;public bool equipCompleted;public double scale,seconds,weight;public DetailRates before,after;}
 [Serializable]public sealed class DetailCases{public DetailCase[] rows;}
 public sealed class ItemDetailTests {
  static void Number(ScientificNumber actual,NumberData expected,string label){var e=ScientificNumber.FromData(expected);if(e.IsZero)Assert.That(actual.IsZero,Is.True,label);else Assert.That(actual.Log10(),Is.EqualTo(e.Log10()).Within(2e-12),label);}
  static void Rates(GameState s,DetailRates expected,string label){Number(Game.Compute(s),expected.compute,label+" compute");Number(Game.Income(s),expected.income,label+" income");Number(Game.DataRate(s),expected.data,label+" data");Number(Game.TrainingCost(s,"quality"),expected.quality,label+" quality");Number(Game.TrainingCost(s,"efficiency"),expected.efficiency,label+" efficiency");}
  [Test]public void ActualSourceSpecialUnitsAndHypotheticalLevelPricesMatchWithoutMutation(){var f=JsonUtility.FromJson<DetailCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/ItemDetailReference.json")));var codec=new UnitySaveCodec();foreach(var row in f.rows){var s=UnityWebImport.Validate(row.transfer);string original=codec.Encode(StateData.From(s));var item=s.Workshop.inventory.First(i=>i.id==row.id);var q=ItemDetailRules.Special(s,item);Assert.That(q.Scale,Is.EqualTo(row.scale).Within(1e-12),row.name);Assert.That(q.BonusSeconds,Is.EqualTo(row.seconds).Within(1e-12),row.name);Assert.That(q.INTWeight,Is.EqualTo(row.weight).Within(1e-12),row.name);Assert.That(q.Active,Is.False);var preview=ItemDetailRules.Upgrade(s,row.id);Rates(preview.Before,row.before,row.name+" before");Rates(preview.After,row.after,row.name+" after");Assert.That(codec.Encode(StateData.From(s)),Is.EqualTo(original),"Preview may not equip, spend or upgrade");var equipped=Workshop.Equip(s,row.id,preview.Slot);var unequipped=Workshop.Unequip(equipped,preview.Slot);Assert.That(unequipped.Retention.onboardingCompleted.Contains("equip-item"),Is.EqualTo(row.equipCompleted),"Real equip evidence must persist even before a simulation tick");}}
 }
}
